import copy
out=copy.deepcopy(rows)
for i,r in enumerate(rows):
    inds=[j for j,v in enumerate(r) if v==0]
    if len(inds)>=3:
        for j in range(min(inds),max(inds)+1):
            if rows[i][j]==1: out[i][j]=2
for j in range(22):
    inds=[i for i in range(12) if rows[i][j]==0]
    if len(inds)>=2:
        for i in range(min(inds),max(inds)+1):
            if rows[i][j]==1: out[i][j]=2
print('\n'.join(' '.join(map(str,r)) for r in out))
print('col counts',[(j,sum(row[j]==0 for row in rows)) for j in range(22) if sum(row[j]==0 for row in rows)>=2])

out2=copy.deepcopy(rows)
# horizontal rows with >=3 zeros
for i,r in enumerate(rows):
    idx=[j for j,v in enumerate(r) if v==0]
    if len(idx)>=3:
        for j in range(min(idx),max(idx)+1):
            if r[j]==1: out2[i][j]=2
# extreme occupied columns only
occupied=[j for j in range(22) if any(r[j]==0 for r in rows)]
for j in [min(occupied),max(occupied)]:
    idx=[i for i,r in enumerate(rows) if r[j]==0]
    for i in range(min(idx),max(idx)+1):
        if rows[i][j]==1: out2[i][j]=2
print('\n'.join(str(r) for r in out2))
